insert into delivery_window (entity_id, zone_id, label, starts, ends, stops_cap, pieces_cap, cube_cap, labor_min_cap)
select z.entity_id, z.id, w.label, w.s::time, w.e::time, w.stops, w.pcs, w.cube, w.lab
  from delivery_zone z cross join (values ('8–12','08:00','12:00',6,30,900,300), ('12–4','12:00','16:00',6,30,900,300)) w(label,s,e,stops,pcs,cube,lab)
 where z.id in ('a2a2a2a2-0000-0000-0000-000000000001','a2a2a2a2-0000-0000-0000-000000000002','a2a2a2a2-0000-0000-0000-000000000003',
                'a2a2a2a2-0000-0000-0000-000000000004','a2a2a2a2-0000-0000-0000-000000000005','a2a2a2a2-0000-0000-0000-0000000000e1');

